     3	/// <summary>Balaye le domaine de la spécification et compare à un oracle écrit indépendamment.</summary>
     4	public class DomainSweepTests
     5	{
     6	    private static readonly Denomination?[] Jams = [null, Denomination.Fifty, Denomination.Twenty, Denomination.Ten];
     7	
     8	    private static readonly int[] Amounts = [-10, 0, 5, .. Enumerable.Range(1, 22).Select(i => i * 10)];
     9	
    10	    private static IEnumerable<NoteCounts> Stocks()
    11	    {
    12	        for (var f = 0; f <= 5; f++)
    13	        for (var t = 0; t <= 5; t++)
    14	        for (var n = 0; n <= 5; n++)
    15	        {
    16	            yield return new NoteCounts(f, t, n);
    17	        }
    18	    }
    19	
    20	    private static AtmResult ExpectedWithdraw(AccountState account, NoteCounts stock, Denomination? jammed, int amount)
    21	    {
    22	        var refused = (AtmStatus s) => new AtmResult(s, NoteCounts.None, 0, account);
    23	        if (amount <= 0 || amount % 10 != 0) return refused(AtmStatus.InvalidAmount);
    24	        if (account.WithdrawnToday + amount > 200) return refused(AtmStatus.DailyLimitExceeded);
    25	        var fee = amount > 100 ? 5 : 0;
    26	        if (amount + fee > account.Balance) return refused(AtmStatus.InsufficientFunds);
    27	
    28	        var available = new NoteCounts(
    29	            jammed == Denomination.Fifty ? 0 : stock.Fifties,
    30	            jammed == Denomination.Twenty ? 0 : stock.Twenties,
    31	            jammed == Denomination.Ten ? 0 : stock.Tens);
    32	        var candidates = Stocks()
    33	            .Where(c => c.Fifties <= available.Fifties && c.Twenties <= available.Twenties && c.Tens <= available.Tens)
    34	            .Where(c => c.Value == amount)
    35	            .ToList();
    36	        if (candidates.Count == 0) return refused(AtmStatus.CannotDispense);
    37	
    38	        var min = candidates.Min(c => c.Total);
    39	        var best = Assert.Single(candidates, c => c.Total == min);
    40	
    41	        return new AtmResult(AtmStatus.Ok, best, fee, new AccountState(account.Balance - amount - fee, account.WithdrawnToday + amount));
    42	    }
    43	
    44	    private static void CheckWithdraw(AccountState account, NoteCounts stock, Denomination? jammed, int amount)
    45	    {
    46	        var dispenser = new SpyDispenser(stock, jammed);
    47	        var actual = new CashMachine(dispenser).Execute(account, new Operation.Withdraw(amount));
    48	        var expected = ExpectedWithdraw(account, stock, jammed, amount);
    49	
    50	        Assert.Equal(expected, actual);
    51	        Assert.Equal(stock - expected.Notes, dispenser.Stock);
    52	        Assert.All(dispenser.Dispensed, pass => Assert.InRange(pass.Total, 1, 4));
    53	    }
    54	
    55	    [Fact]
    56	    public void Withdraw_matches_oracle_for_every_stock_jam_and_amount()
    57	    {
    58	        foreach (var account in new[] { new AccountState(250, 0), new AccountState(105, 60), new AccountState(0, 0) })
    59	        foreach (var stock in Stocks())
    60	        foreach (var jammed in Jams)
    61	        foreach (var amount in Amounts)
    62	        {
    63	            CheckWithdraw(account, stock, jammed, amount);
    64	        }
    65	    }
    66	
    67	    [Fact]
    68	    public void Withdraw_matches_oracle_for_every_account_and_amount()
    69	    {
    70	        for (var balance = 0; balance <= 250; balance += 5)
    71	        for (var withdrawn = 0; withdrawn <= 200; withdrawn += 10)
    72	        foreach (var amount in Amounts)
    73	        {
