    79	    [Fact]
    80	    public void Deposit_matches_oracle_over_the_domain()
    81	    {
    82	        var account = new AccountState(35, 70);
    83	        foreach (var stock in Stocks())
    84	        foreach (var jammed in Jams)
    85	        for (var mask = 0; mask < 8; mask++)
    86	        {
    87	            var notes = new NoteCounts(mask & 1, (mask >> 1) & 1, (mask >> 2) & 1);
    88	            var dispenser = new SpyDispenser(stock, jammed);
    89	            var actual = new CashMachine(dispenser).Execute(account, new Operation.Deposit(notes));
    90	
    91	            var after = stock + notes;
    92	            AtmStatus status =
    93	                notes.Total == 0 ? AtmStatus.InvalidAmount
    94	                : jammed is { } j && notes.Of(j) > 0 ? AtmStatus.CassetteJammed
    95	                : after.Fifties > 5 || after.Twenties > 5 || after.Tens > 5 ? AtmStatus.CassetteFull
    96	                : AtmStatus.Ok;
    97	
    98	            var ok = status == AtmStatus.Ok;
    99	            Assert.Equal(new AtmResult(status, NoteCounts.None, 0, ok ? account with { Balance = 35 + notes.Value } : account), actual);
