     3	/// <summary>
     4	/// Tests d'intégration : <see cref="CashMachine"/> travaille avec le vrai <see cref="MoneyDispenser"/>, sans doublure.
     5	/// Après chaque opération, on vérifie le résultat rendu et le stock réellement présent dans le module.
     6	/// </summary>
     7	public class Integration
     8	{
     9	    private static readonly NoteCounts Full = new(5, 5, 5);
    10	
    11	    private static readonly NoteCounts Empty = new(0, 0, 0);
    12	
    13	    private static readonly Denomination?[] Jams = [null, Denomination.Fifty, Denomination.Twenty, Denomination.Ten];
    14	
    15	    private static readonly int[] Amounts = [-10, 0, 5, .. Enumerable.Range(1, 22).Select(i => i * 10)];
