    24	    private static IEnumerable<NoteCounts> Stocks()
    25	    {
    26	        for (var f = 0; f <= 5; f++)
    27	        for (var t = 0; t <= 5; t++)
    28	        for (var n = 0; n <= 5; n++)
    29	        {
    30	            yield return new NoteCounts(f, t, n);
    31	        }
    32	    }
    33	
    34	    private static IEnumerable<AccountState> Accounts()
    35	    {
    36	        for (var balance = 0; balance <= 250; balance += 5)
    37	        for (var withdrawn = 0; withdrawn <= 200; withdrawn += 10)
    38	        {
    39	            yield return new AccountState(balance, withdrawn);
    40	        }
    41	    }
