    43	    private static bool InDomain(AccountState a) =>
    44	        a.Balance is >= 0 and <= 250 && a.Balance % 5 == 0 && a.WithdrawnToday is >= 0 and <= 200 && a.WithdrawnToday % 10 == 0;
    45	
    46	    private static AtmResult Refused(AtmStatus status, AccountState account) => new(status, NoteCounts.None, 0, account);
    47	
    48	    /// <summary>Oracle indépendant de l'implémentation : recherche exhaustive de la combinaison.</summary>
    49	    private static AtmResult ExpectedWithdraw(AccountState account, NoteCounts stock, Denomination? jammed, int amount)
    50	    {
    51	        if (amount <= 0 || amount % 10 != 0) return Refused(AtmStatus.InvalidAmount, account);
    52	        if (account.WithdrawnToday + amount > 200) return Refused(AtmStatus.DailyLimitExceeded, account);
    53	        var fee = amount > 100 ? 5 : 0;
    54	        if (amount + fee > account.Balance) return Refused(AtmStatus.InsufficientFunds, account);
    55	
    56	        var usable = new NoteCounts(
    57	            jammed == Denomination.Fifty ? 0 : stock.Fifties,
    58	            jammed == Denomination.Twenty ? 0 : stock.Twenties,
    59	            jammed == Denomination.Ten ? 0 : stock.Tens);
    60	
    61	        var candidates = new List<NoteCounts>();
    62	        for (var f = 0; f <= usable.Fifties; f++)
    63	        for (var t = 0; t <= usable.Twenties; t++)
    64	        for (var n = 0; n <= usable.Tens; n++)
    65	        {
    66	            var c = new NoteCounts(f, t, n);
    67	            if (c.Value == amount) candidates.Add(c);
    68	        }
    69	
    70	        if (candidates.Count == 0) return Refused(AtmStatus.CannotDispense, account);
    71	
    72	        var fewest = candidates.Min(c => c.Total);
    73	        var best = Assert.Single(candidates, c => c.Total == fewest);
    74	
    75	        return new AtmResult(AtmStatus.Ok, best, fee, new AccountState(account.Balance - amount - fee, account.WithdrawnToday + amount));
    76	    }
    77	
    78	    private static AtmResult ExpectedDeposit(AccountState account, NoteCounts stock, Denomination? jammed, NoteCounts notes)
    79	    {
    80	        if (notes.Total == 0) return Refused(AtmStatus.InvalidAmount, account);
    81	        if (jammed is { } j && notes.Of(j) > 0) return Refused(AtmStatus.CassetteJammed, account);
    82	        var after = stock + notes;
    83	        if (after.Fifties > 5 || after.Twenties > 5 || after.Tens > 5) return Refused(AtmStatus.CassetteFull, account);
    84	
    85	        return new AtmResult(AtmStatus.Ok, NoteCounts.None, 0, account with { Balance = account.Balance + notes.Value });
    86	    }
    87	
    88	    private static AtmResult Expected(AccountState account, NoteCounts stock, Denomination? jammed, Operation op) => op switch
    89	    {
    90	        Operation.Withdraw w => ExpectedWithdraw(account, stock, jammed, w.Amount),
    91	        Operation.Deposit d => ExpectedDeposit(account, stock, jammed, d.Notes),
    92	        _ => throw new ArgumentException("Opération inconnue.", nameof(op)),
    93	    };
    94	
    95	    /// <summary>Le stock attendu dans le module après un résultat réussi (rien ne bouge sinon).</summary>
    96	    private static NoteCounts ExpectedStock(NoteCounts before, Operation op, AtmResult expected) =>
    97	        expected.Status != AtmStatus.Ok ? before
    98	        : op is Operation.Deposit d ? before + d.Notes
    99	        : before - expected.Notes;
   100	
   101	    /// <summary>Exécute une opération avec la machine et le module donnés, et vérifie résultat et stock.</summary>
   102	    private static AtmResult Check(CashMachine machine, MoneyDispenser dispenser, AccountState account, Operation op)
   103	    {
   104	        var before = dispenser.Stock;
   105	        var jammed = dispenser.Jammed;
   106	        var expected = Expected(account, before, jammed, op);
   107	
   108	        var actual = machine.Execute(account, op);
   109	
   110	        Assert.Equal(expected, actual);
   111	        Assert.NotEqual(AtmStatus.DispenserFault, actual.Status);
   112	        Assert.Equal(ExpectedStock(before, op, expected), dispenser.Stock);
   113	        Assert.Equal(jammed, dispenser.Jammed);
   114	
   115	        return actual;
   116	    }
   117	
   118	    private static AtmResult CheckFresh(AccountState account, NoteCounts stock, Denomination? jammed, Operation op)
   119	    {
   120	        var dispenser = new MoneyDispenser(stock, jammed);
   121	
   122	        return Check(new CashMachine(dispenser), dispenser, account, op);
   123	    }
