    {
        // 150 € sans billets de 50 : 20×5 + 10×5, dix billets, donc au moins trois passages de 4 au plus.
        var dispenser = new MoneyDispenser(new NoteCounts(4, 5, 5), Denomination.Fifty);
        var machine = new CashMachine(dispenser);

