        var result = machine.Execute(account, new Operation.Withdraw(50));
        Assert.Equal(new AtmResult(AtmStatus.Ok, new(1, 0, 0), 0, new(200, 50)), result);
        Assert.Equal(Empty, dispenser.Stock);
