import re, json, itertools
src=open('/tmp/orig/Atm/CashMachine.cs').read().replace(open('/tmp/orig/Atm/CashMachine.cs').read(),open('/travail/Atm/CashMachine.cs').read())
lines=src.split('\n')
muts=[]
rel=[('<=','<'),('<','<='),('>=','>'),('>','>='),('==','!='),('!=','==')]
rel_alt={'<=':['<','>=','=='],'<':['<=','>','!='],'>=':['>','<=','=='],'>':['>=','<','!='],'==':['!=','<=','>='],'!=':['==','<','>']}
for i,l in enumerate(lines):
    s=l.strip()
    if s.startswith('//') or s.startswith('///') or 'namespace' in s or 'using' in s: continue
    for m in re.finditer(r'(?<![<>=!])(<=|>=|==|!=|<|>)(?![<>=])',l):
        op=m.group(1)
        if l[m.start()-1:m.start()]=='=' : continue
        if '=>' in l[m.start()-1:m.end()+1]: continue
        for alt in rel_alt[op]:
            muts.append((i, l[:m.start()]+alt+l[m.end():]))
    for m in re.finditer(r'(?<=[\s(])([-+])(?=[\s])',l):
        alt={'+':'-','-':'+'}[m.group(1)]
        muts.append((i,l[:m.start()]+alt+l[m.end():]))
    for m in re.finditer(r'\|\||&&',l):
        alt={'||':'&&','&&':'||'}[m.group(0)]
        muts.append((i,l[:m.start()]+alt+l[m.end():]))
